  str_homestory_N24diaoyu_90050101_9_dialog_content = "<sprite=emo_dianzan size=60 />เป็นความคิดที่ดีมาก! ขอคิดก่อนนะ...",
  str_homestory_N24diaoyu_90050101_10_dialog_content = "แต่จะต้องใช้เงินเป็นจำนวนมาก<sprite=emo_baiyebi size=60 />",
  str_homestory_N24diaoyu_90050101_11_dialog_content = "แน่นอน. พิพิธภัณฑ์ต้องการอุปกรณ์จำนวนมากเพื่อปกป้องของสะสม",
  str_homestory_N24diaoyu_90050101_12_dialog_content = "อย่างระบบควบคุมอุณหภูมิ ความชื้น และ...",
