  str_homestory_N24diaoyu_90050101_32_dialog_content = "<sprite=emo_chidai size=60 />ว้าว... คุณกลายเป็นผู้ให้คำปรึกษาที่ดีจริงๆ PlayerName.",
  str_homestory_N24diaoyu_90050101_33_dialog_content = "เป็นอย่างใดอย่างหนึ่งหรือนั่นเป็นเพียงการพูดคุยในส่วนของคุณ",
  str_homestory_N24diaoyu_90050101_34_dialog_content = "ฮะฮะ...",
