  str_homestory_N24diaoyu_90050101_36_dialog_content = "Barton, Fia และตอนนี้ Fleur... ทำไมพวกเขาถึงรีบร้อน?",
  str_homestory_N24diaoyu_90050101_37_dialog_content = "ฉันไม่สามารถยืนนี้ ฉันต้องติดต่อกับพวกเขาและดูว่าเกิดอะไรขึ้น",
  str_homestory_N24diaoyu_90050102_1_dialog_content = "<sprite=emo_hanshui size=60 />ฟุ่บ ฟุ่บ!",
