  str_homestory_N24diaoyu_90050102_4_dialog_content = "ฉัน... ฉันกำลังพยายามไล่ให้ทันเฟลอร์",
  str_homestory_N24diaoyu_90050102_5_dialog_content = "และฉันพยายามเป็นเพื่อนที่ดีกับเขา",
  str_homestory_N24diaoyu_90050102_6_dialog_content = "ยังไง... เฟลอร์วิ่งเร็วขนาดนั้นได้ยังไง? เขาดูไม่เหมือนนักกีฬา",
  str_homestory_N24diaoyu_90050102_7_dialog_content = "จริงหรือ ฉันเห็นเฟลอร์วิ่งจ๊อกกิ้งรอบๆ Cloud Gardens ค่อนข้างบ่อย",
  str_homestory_N24diaoyu_90050102_8_dialog_content = "อะไร นั่นคือตัวตนของเขาจริงๆ เหรอ? <sprite=emo_tanqi size=60 />อาจหลอกฉันได้...",
  str_homestory_N24diaoyu_90050102_9_dialog_content = "ทำไมคุณถึงตามหาเฟลอร์ PlayerName?",
