  str_homestory_N24diaoyu_90050102_13_dialog_content = "นั่นคือคำจำกัดความของ \"เพื่อความสนุก\" ใช่ไหม<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050102_14_dialog_content = "ฉันคิดว่าฉันรู้ว่าเฟลอร์กำลังทำอะไรอยู่",
