  str_homestory_N24diaoyu_90050102_17_dialog_content = "<sprite=emo_sikao size=60 />ตกปลา...?",
  str_homestory_N24diaoyu_90050102_18_dialog_content = "ใช่. ฉันได้ยินมาว่ามันเป็นงานที่จัดขึ้นร่วมกันโดยสำนักพิมพ์และกิลด์หลายแห่งของ Umbraton ซึ่งแนะนำโดย Rediesel Desert Aurorian",
  str_homestory_N24diaoyu_90050102_19_dialog_content = "นี้ \"<color=#FFB400>จับพิเศษ</color>\"งานประกวดตกปลากลายเป็นที่ฮือฮากันเลยทีเดียว\" เรียกผู้เข้าแข่งขันว่า <color=#FFB400>นักตกปลา</color>.",
  str_homestory_N24diaoyu_90050102_20_dialog_content = "เฟลอร์ต้องเข้าร่วมการแข่งขันและพยายามแข่งขันกับนักตกปลาคนอื่นๆ",
  str_homestory_N24diaoyu_90050102_21_dialog_content = "รางวัลใหญ่ของงานแบบนี้ต้องเป็นของที่ระลึกหรืออะไรซักอย่าง... ไม่นึกว่าเฟลอร์จะสนใจขนาดนี้",
  str_homestory_N24diaoyu_90050102_22_dialog_content = "ฉันไม่คิดว่าเป็นกรณี รางวัลดังกล่าวเป็น <color=#FFB400>คันเบ็ดทองคำบริสุทธิ์หุ้มด้วย Lumamber</color>.",
  str_homestory_N24diaoyu_90050102_23_dialog_content = "ทองคำบริสุทธิ์ คุณว่าไหม...?",
  str_homestory_N24diaoyu_90050102_24_dialog_content = "และหุ้มด้วย Lumamber...",
  str_homestory_N24diaoyu_90050102_25_dialog_content = "<sprite=emo_mojing size=60 />อะแฮ่ม! คาร์ลีน คุณต้องรู้ว่าคนใน Cloud Gardens เรียกฉันว่า \"Dragonwave Angler\"",
  str_homestory_N24diaoyu_90050102_26_dialog_content = "ไม่มีทางที่ฉันจะปล่อยให้พวกมันแย่งปลาไปจากฉัน!",
  str_homestory_N24diaoyu_90050102_27_dialog_content = "(ถ้าชนะจะมีทุนสร้างพิพิธภัณฑ์!<sprite=emo_baiyebi size=60 />)",
  str_homestory_N24diaoyu_90050102_28_dialog_content = "คุณต้องการที่จะเข้าร่วม?",
