  str_homestory_N24diaoyu_90050103_4_dialog_content = "เกือบ! ฉันชอบที่มันเจาะลึกถึงอารมณ์ของตัวเอกจริงๆ!",
  str_homestory_N24diaoyu_90050103_5_dialog_content = "และความสัมพันธ์ของเขากับ Genie เพื่อนจักรกลของเขาก็น่าประทับใจเช่นกัน!<sprite=emo_caitiao size=60 />",
