  str_homestory_N24diaoyu_90050103_11_dialog_content = "คุณล้อฉันเล่น? ฉันคือ Dragonwave Angler ที่มีชื่อเสียงของ Cloud Gardens!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050103_12_dialog_content = "ฉันสนใจรางวัลใหญ่มาก!<sprite=emo_baiyebi size=60 />",
