  str_homestory_N24diaoyu_90050103_21_dialog_content = "อาจจะ... ฉันหมายความว่าเขากำลังพยายามคิดชื่อสำหรับการคัดเลือกนักแสดงของเขาด้วยซ้ำ",
  str_homestory_N24diaoyu_90050103_22_dialog_content = "ก็...มีวิธีอยู่",
