  str_homestory_N24diaoyu_90050103_24_dialog_content = "ฉันหมายความว่ามันเป็นการแข่งขันที่จะสนุกก็ต่อเมื่อมีผู้เข้าแข่งขันจำนวนมาก",
  str_homestory_N24diaoyu_90050103_25_dialog_content = "และยังเป็นหน้าที่ของผมที่จะต้องแน่ใจว่านักตกปลาที่ดีมีโอกาสฉายแสง",
  str_homestory_N24diaoyu_90050103_26_dialog_content = "แต่คุณต้องพิสูจน์ตัวเองให้ฉันเห็นก่อน",
  str_homestory_N24diaoyu_90050103_27_dialog_content = "คุณกำลังแนะนำอะไร",
