  str_homestory_N24diaoyu_90050104_5_dialog_content = "เร็วจัง",
  str_homestory_N24diaoyu_90050104_6_dialog_content = "<sprite=emo_dianzan size=60 />ดูเหมือน PlayerName ไม่ได้ล้อเล่นจริงๆ",
  str_homestory_N24diaoyu_90050104_7_dialog_content = "เฮ้! แน่นอน! ฉันกลับมาที่นี่ทันทีที่จับปลาได้!",
  str_homestory_N24diaoyu_90050104_8_dialog_content = "พวกเขายังไม่กลับมาอีกเหรอ?",
  str_homestory_N24diaoyu_90050104_9_dialog_content = "ไม่. ตามสัญญา คุณจะได้รับคันเบ็ดเป็นคันแรก PlayerName.",
  str_homestory_N24diaoyu_90050104_10_dialog_content = "นั่นคือของขวัญเซอร์ไพรส์ที่คุณพูดถึง?",
  str_homestory_N24diaoyu_90050104_11_dialog_content = "ใช่. เราได้เตรียมเบ็ดตกปลาที่แตกต่างกันมากมายสำหรับผู้เข้าแข่งขันของเรา เฉพาะนักตกปลาที่ผ่านการรับรองเท่านั้นที่จะถือคันเบ็ดที่ผ่านการรับรองของเราได้",
  str_homestory_N24diaoyu_90050104_12_dialog_content = "แล้วคุณจะได้อะไร? คันเบ็ด ไฟ น้ำ หรือหญ้า?",
  str_homestory_N24diaoyu_90050104_13_dialog_content = "อืม... ต่างกันยังไง?",
  str_homestory_N24diaoyu_90050104_14_dialog_content = "คุณจะต้องค้นหาด้วยตัวคุณเอง! บางทีมันอาจจะทำให้คุณมีทักษะพิเศษหรือเติบโตไปพร้อมกับคุณ หรืออาจจะไม่แตกต่างกันเลย!",
  str_homestory_N24diaoyu_90050104_15_dialog_content = "มันก็แค่เบ็ดตกปลา แต่เมื่อคุณเลือกแล้ว มันจะกลายเป็นเพื่อนที่ดีที่สุดของคุณ",
  str_homestory_N24diaoyu_90050104_16_dialog_content = "แล้วฉันจะเลือก...",
  str_homestory_N24diaoyu_90050104_17_option_content = "คันเบ็ดหญ้า!",
  str_homestory_N24diaoyu_90050104_18_option_content = "คันเบ็ดไฟลุก!",
  str_homestory_N24diaoyu_90050104_19_option_content = "คันเบ็ดน้ำ!",
  str_homestory_N24diaoyu_90050104_20_dialog_content = "ว้าว! ถือแล้วรู้สึกดี!",
  str_homestory_N24diaoyu_90050104_21_dialog_content = "<sprite=emo_tanqi size=60 />แต่ฉันไม่คิดว่ามันมีความสามารถพิเศษอะไรพวกนั้น...",
  str_homestory_N24diaoyu_90050104_22_dialog_content = "ฉันกลับมาแล้ว",
  str_homestory_N24diaoyu_90050104_23_dialog_content = "คุณกลับมาแล้ว คาร์ลีน",
  str_homestory_N24diaoyu_90050104_24_dialog_content = "โปรดเลือกเบ็ดตกปลาจากสองอันที่เหลือ",
  str_homestory_N24diaoyu_90050104_25_dialog_content = "อะไรก็ตาม... ใครๆ ก็ทำได้",
  str_homestory_N24diaoyu_90050104_26_dialog_content = "ตอนนี้คุณมีคันเบ็ดแล้ว ทำไมคุณไม่ลองมันดูล่ะ?",
  str_homestory_N24diaoyu_90050104_27_dialog_content = "เริ่มการแข่งขันรอบแรกระหว่างรอ Vice กลับมา",
  str_homestory_N24diaoyu_90050104X_1_dialog_content = "PlayerNameคันเบ็ดของคุณดูทรงพลัง",
  str_homestory_N24diaoyu_90050104X_2_dialog_content = "เตรียมแข่งกับผมก่อนมั้ย?",
  str_homestory_N24diaoyu_90050104X_3_option_content = "ฉันพร้อม",
  str_homestory_N24diaoyu_90050104X_4_option_content = "ยังเลย",
  str_homestory_N24diaoyu_90050105_1_dialog_content = "คุณเก่งเรื่องนี้มาก PlayerName.",
  str_homestory_N24diaoyu_90050105_2_dialog_content = "คุณแน่ใจว่าเป็นนักตกปลาโดยธรรมชาติ PlayerName.",
  str_homestory_N24diaoyu_90050105_3_dialog_content = "<sprite=emo_guilian size=60 />หึหึ ไม่ใช่แค่นั้น ฉันได้ฝึกฝนมากมายใน Cloud Gardens!",
  str_homestory_N24diaoyu_90050105_4_dialog_content = "(นั่นและหลายคนขอให้ฉันหาปลาทุกชนิดให้พวกเขา)",
  str_homestory_N24diaoyu_90050105_5_dialog_content = "ฮะ? พวกคุณเร็วมาก ฉันจับได้แค่นี้ก็พอแล้ว",
  str_homestory_N24diaoyu_90050105_6_dialog_content = "ไม่เป็นไร รอง เราทุกคนกำลังรอคุณอยู่",
  str_homestory_N24diaoyu_90050105_7_dialog_content = "นี่คือเบ็ดตกปลาของคุณ ตอนนี้คุณเป็นนักตกปลาแล้ว!",
  str_homestory_N24diaoyu_90050105_8_dialog_content = "จากนั้น ฉันจะรอพบคุณในการแข่งขัน—",
  str_homestory_N24diaoyu_90050105_9_dialog_content = "สำหรับแชมป์—",
  str_homestory_N24diaoyu_90050105_10_dialog_content = "สำหรับพิพิธภัณฑ์—",
  str_homestory_N24diaoyu_90050105_11_dialog_content = "สำหรับ Lumamber—",
  str_homestory_N24diaoyu_90050105_12_dialog_content = "<sprite=emo_caitiao size=60 />ขอให้โชคดี!",
  str_homestory_N24diaoyu_90050201_1_dialog_content = "ถูกต้อง. ตอนนี้ฉันเป็นนักตกปลาที่ได้รับการอนุมัติแล้ว ฉันจะเริ่มการเดินทางสู่การเป็นแชมป์เปี้ยน!",
  str_homestory_N24diaoyu_90050201_2_dialog_content = "สิ่งแรกก่อน!",
  str_homestory_N24diaoyu_90050201_3_dialog_content = "อืม... อย่างแรก...",
  str_homestory_N24diaoyu_90050201_4_dialog_content = "<sprite=emo_xiaoku size=60 />ฉัน... ไม่คิดว่าฉันคุ้นเคยกับกฎ",
  str_homestory_N24diaoyu_90050201_5_dialog_content = "ที่น่าอาย ไล่ตามเบเธลพร้อมกับคำถามหลังจากคำพูดแบบนั้น...",
  str_homestory_N24diaoyu_90050201_6_dialog_content = "นั่นไม่เหมือนแชมป์เปี้ยน",
  str_homestory_N24diaoyu_90050201_7_dialog_content = "ทุกคนควรรู้เกี่ยวกับกฎ ดังนั้นถ้าฉันถามคนอื่นก็เหมือนกัน! ถูกต้อง!",
  str_homestory_N24diaoyu_90050201_8_dialog_content = "อืม? ลิลิก้าอยู่ตรงนั้นไม่ใช่เหรอ? เธอมาจาก Umbraton และเธอรู้ทุกอย่าง",
  str_homestory_N24diaoyu_90050201_9_dialog_content = "ฉันควรจะไปถามเธอ",
  str_homestory_N24diaoyu_90050202_1_dialog_content = "ลิลิก้า.",
  str_homestory_N24diaoyu_90050202_2_dialog_content = "<sprite=emo_laba size=60 />ลิลิก้า—",
  str_homestory_N24diaoyu_90050202_3_dialog_content = "เอ๋?!",
  str_homestory_N24diaoyu_90050202_4_dialog_content = "ต-ตกใจหมดเลย...",
  str_homestory_N24diaoyu_90050202_5_dialog_content = "ไม่คาดคิดว่าจะได้พบคุณที่นี่ PlayerName.",
  str_homestory_N24diaoyu_90050202_6_dialog_content = "ฉันเพิ่งเกิดไอเดียที่ไม่ธรรมดาสำหรับฉากหนึ่ง!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050202_7_dialog_content = "ขออภัยที่ก้าวก่ายความคิดของคุณแล้ว!",
  str_homestory_N24diaoyu_90050202_8_dialog_content = "โอ้ ไม่เป็นไร แรงบันดาลใจของฉันก็แห้งเหือดอยู่ดี ฉันกำลังจะหยุดพัก",
  str_homestory_N24diaoyu_90050202_9_dialog_content = "แล้วคุณต้องการอะไร?",
  str_homestory_N24diaoyu_90050202_10_dialog_content = "จริงๆ แล้วคุณค่อนข้างรอบรู้ที่นี่",
  str_homestory_N24diaoyu_90050202_11_dialog_content = "โอ้? นั่นเป็นคำชมที่ดี คุณประชดฉันเพื่ออะไร",
  str_homestory_N24diaoyu_90050202_12_dialog_content = "คุณรู้เกี่ยวกับการแข่งขันตกปลาที่ชื่อว่า An Extraordinary Catch หรือไม่?",
  str_homestory_N24diaoyu_90050202_13_dialog_content = "แน่นอน. เป็นสิ่งที่ทุกคนพูดถึงเมื่อเร็ว ๆ นี้",
  str_homestory_N24diaoyu_90050202_14_dialog_content = "ใช่... บางทีฉันอาจจะเขียนบทเกี่ยวกับการตกปลาก็ได้",
  str_homestory_N24diaoyu_90050202_15_dialog_content = "ตัวเอกเป็นพี่ชายสองคนและพ่อของพวกเขาเป็นครู พี่ชายคนโตเป็นคนดีและซื่อสัตย์และสืบทอดกิจการของครอบครัวหลังจากเรียนจบ",
  str_homestory_N24diaoyu_90050202_16_dialog_content = "และน้องชายเป็นคนโรแมนติกและรักธรรมชาติ เขาได้เรียนรู้วิธีการตกปลาแบบพิเศษ",
  str_homestory_N24diaoyu_90050202_17_dialog_content = "อย่างไรก็ตามเขาติดการพนันและหลุดพ้นได้ด้วยความช่วยเหลือจากพี่ชายของเขาเท่านั้น",
  str_homestory_N24diaoyu_90050202_18_dialog_content = "W-รอสักครู่... คุณสามารถทำได้ในภายหลัง",
  str_homestory_N24diaoyu_90050202_19_dialog_content = "หลังจากที่คุณบอกฉันเกี่ยวกับกฎของการแข่งขัน หากคุณทราบ",
  str_homestory_N24diaoyu_90050202_20_dialog_content = "แต่พี่ชายหายตัวไปและน้องชายจับฉลามได้ระหว่างทริปตกปลา",
  str_homestory_N24diaoyu_90050202_21_dialog_content = "เขาพบศพน้องชายของเขาในท้องฉลาม และนี่ก็กลายเป็นคดีฆาตกรรมที่แปลกประหลาด",
  str_homestory_N24diaoyu_90050202_22_dialog_content = "โอ้! ถูกต้อง. คุณกำลังถามฉันเกี่ยวกับกฎ แน่นอน ฉันสามารถช่วยคุณได้",
  str_homestory_N24diaoyu_90050202_23_dialog_content = "จริงเหรอ",
  str_homestory_N24diaoyu_90050202_24_dialog_content = "แต่คุณรู้ว่ามันไปอย่างไร คุณต้องทำบางอย่างให้ฉัน",
  str_homestory_N24diaoyu_90050202_25_dialog_content = "เก็บไม้มาให้ฉันหน่อย ฉันต้องการสร้างชุด",
  str_homestory_N24diaoyu_90050202_26_dialog_content = "ถูกต้อง. ฉันจะกลับมา.",
  str_homestory_N24diaoyu_90050203_1_dialog_content = "หาไม้เจอมั้ย? ฉันกำลังพยายามคิดพล็อตที่ดีที่นี่!",
  str_homestory_N24diaoyu_90050203_2_dialog_content = "พบแล้ว! ({1}/{2})",
  str_homestory_N24diaoyu_90050203_3_dialog_content = "ดีมาก!",
  str_homestory_N24diaoyu_90050203_4_dialog_content = "อีกเพียงเล็กน้อย กลับไปคิดอีกพักนึง!",
  str_homestory_N24diaoyu_90050203_5_dialog_content = "เอาล่ะตกลง แค่รีบขึ้น",
  str_homestory_N24diaoyu_90050203_6_dialog_content = "ดีมาก!",
  str_homestory_N24diaoyu_90050203_7_dialog_content = "รวดเร็ว",
  str_homestory_N24diaoyu_90050203_8_dialog_content = "แน่นอน. ตอนนี้ฉันเชี่ยวชาญในการทำธุระแล้ว!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050203_9_dialog_content = "ก่อนหน้านี้คุณค่อนข้างสะดวกในการถ่ายทำภาพยนตร์ เคยคิดที่จะทำงานที่กองถ่ายบ้างไหม?",
  str_homestory_N24diaoyu_90050203_10_dialog_content = "<sprite=emo_hanshui size=60 />ฮ่าฮ่าฮ่า... ข้าจะลองคิดดู ฉันแค่หวังว่าครั้งต่อไปจะปลอดภัยกว่านี้",
  str_homestory_N24diaoyu_90050203_11_dialog_content = "หึหึ เนื่องจากคุณเป็นปรมาจารย์ด้านนี้ คุณช่วยหาปลาเป็นอาหารเย็นให้ฉันด้วยได้ไหม",
  str_homestory_N24diaoyu_90050203_12_dialog_content = "อืม... คุณค่อนข้างคลั่งไคล้หนังเรื่องล่าสุด ทำไมคุณต้องจับปลาเป็นอาหารเย็นในสวนเมฆา",
  str_homestory_N24diaoyu_90050203_13_dialog_content = "เรียกว่าประหยัด! ฉันเก็บเงินไว้สำหรับภาคต่อของ Into the Haunted House",
  str_homestory_N24diaoyu_90050203_14_dialog_content = "ดี. ฉันจะคิดว่ามันเป็นการฝึกฝนสำหรับการแข่งขัน แค่รอฉันอยู่ตรงนี้",
  str_homestory_N24diaoyu_90050204_1_dialog_content = "อาหารเย็นของฉันอยู่ที่ไหน",
  str_homestory_N24diaoyu_90050204_2_dialog_content = "ว้าว! ปลาดูร่าเริงมาก ({1}/{2})",
  str_homestory_N24diaoyu_90050204_3_dialog_content = "อีกเพียงเล็กน้อย ยังไม่พอใช่ไหม",
  str_homestory_N24diaoyu_90050204_4_dialog_content = "ไม่เป็นไร ฉันยังไม่หิว คุณสามารถลองจับเพิ่มเติม PlayerName.",
  str_homestory_N24diaoyu_90050204_5_dialog_content = "<sprite=emo_caitiao size=60 />โว้ว! นั่นเป็นจำนวนมาก นี่จะเพียงพอสำหรับวัน",
  str_homestory_N24diaoyu_90050204_6_dialog_content = "อืม... คุณวางแผนที่จะจับปลาทุกวันในอีกสองสามวันข้างหน้า?",
  str_homestory_N24diaoyu_90050204_7_dialog_content = "ฉันอาจขอให้เซลลูโลซื้อผลไม้ให้ฉันด้วย",
  str_homestory_N24diaoyu_90050204_8_dialog_content = "(ฉันทำตามที่ลิลิก้าบอกดีกว่า)",
  str_homestory_N24diaoyu_90050204_9_dialog_content = "(ฉันไม่อยากทำร้ายความรู้สึกของเธอด้วยการพูดสิ่งที่ฉันคิด)",
  str_homestory_N24diaoyu_90050204_10_dialog_content = "แล้ว...กฎล่ะ?",
  str_homestory_N24diaoyu_90050204_11_dialog_content = "ถูกต้อง! เกือบลืม.",
  str_homestory_N24diaoyu_90050204_12_dialog_content = "คุณไม่ได้ล้อฉันเล่นใช่ไหม<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050204_13_dialog_content = "ล้อเล่น! ฉันล้อเล่นเท่านั้น!",
  str_homestory_N24diaoyu_90050204_14_dialog_content = "ที่จริงฉันไม่รู้กฎด้วยตัวเอง แต่ฉันรู้จักคนที่ทำ",
  str_homestory_N24diaoyu_90050204_15_dialog_content = "คุณจะต้องผ่านเธอเพื่อที่จะกลายเป็นนักตกปลาตัวจริง",
  str_homestory_N24diaoyu_90050204_16_dialog_content = "เธอหมายความว่าไง",
  str_homestory_N24diaoyu_90050204_17_dialog_content = "เฟีย เธอเป็นผู้สอนและผู้เชี่ยวชาญอย่างเป็นทางการของการประกวด",
  str_homestory_N24diaoyu_90050204_18_dialog_content = "อะไร...เฟีย? ฉันเพิ่งปฏิเสธคำขอของเธอไม่นานมานี้...",
  str_homestory_N24diaoyu_90050204_19_dialog_content = "อืม? มีบางอย่างเกิดขึ้นระหว่างคุณสองคนหรือไม่?",
  str_homestory_N24diaoyu_90050204_20_dialog_content = "เธอไม่ควรเป็นคนเก็บความแค้นใช่ไหม? เพียงแค่พูดคุยกับเธอ",
  str_homestory_N24diaoyu_90050204_21_dialog_content = "ถูกของคุณ!",
  str_homestory_N24diaoyu_90050204_22_dialog_content = "ขอบคุณลิลิก้า! แล้วพบกันใหม่!<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050205_1_dialog_content = "เฮ้ เฟีย—",
  str_homestory_N24diaoyu_90050205_2_dialog_content = "<sprite=emo_emo size=60 />นี่นายภัณฑารักษ์ของพิพิธภัณฑ์ไม่ใช่เหรอ PlayerName?",
  str_homestory_N24diaoyu_90050205_3_dialog_content = "ฉันคิดว่าคุณเป็นคนยุ่ง",
  str_homestory_N24diaoyu_90050205_4_dialog_content = "อืม... ยังอารมณ์เสียอยู่เหรอ?",
  str_homestory_N24diaoyu_90050205_5_dialog_content = "(ได้เวลาริเริ่มที่จะขอโทษแล้ว!)",
  str_homestory_N24diaoyu_90050205_6_dialog_content = "<sprite=emo_tanqi size=60 />ฉันขอโทษสำหรับก่อนหน้านี้ มันเป็นความผิดพลาดของฉัน และฉันได้เรียนรู้จากความผิดพลาดของฉัน!",
  str_homestory_N24diaoyu_90050205_7_dialog_content = "ฮึ คุณจึงไม่มีข้อแก้ตัวใดๆ ดี.",
  str_homestory_N24diaoyu_90050205_8_dialog_content = "คุณมาที่นี่เพราะการแข่งขันใช่ไหม",
  str_homestory_N24diaoyu_90050205_9_dialog_content = "ถูกตัอง. ฉันรู้ว่าคุณจะไม่ถือโทษโกรธ Fia!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050205_10_dialog_content = "อย่าเพิ่งขอบคุณฉัน ฉันไม่ได้บอกว่าฉันจะช่วยคุณ",
  str_homestory_N24diaoyu_90050205_11_dialog_content = "ถ้าจะเข้าประกวดต้องเอาชนะข้าให้ได้ก่อน",
  str_homestory_N24diaoyu_90050205_12_dialog_content = "ตอนนี้, PlayerNameแสดงให้ฉันเห็นว่าคุณมีอะไร!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050205X_1_dialog_content = "เราจะเริ่มได้ยัง? ฉันเป็นคนที่ยุ่งมาก",
  str_homestory_N24diaoyu_90050205X_2_option_content = "ได้เลยค่ะ",
  str_homestory_N24diaoyu_90050205X_3_option_content = "ทันใดนั้นฉันก็นึกขึ้นได้ว่ามีบางอย่างที่ฉันต้องทำ!",
  str_homestory_N24diaoyu_90050206_1_dialog_content = "อืม...! เฟีย ฉันไม่ได้คาดหวังว่าคุณจะดีขนาดนี้",
  str_homestory_N24diaoyu_90050206_2_dialog_content = "ฮะ? ไม่เลว. ไม่เลว. ฉันประทับใจเล็กน้อย คุณผ่าน.",
  str_homestory_N24diaoyu_90050206_3_dialog_content = "ตอนนี้ฉันรู้สึกดีขึ้นเล็กน้อยหลังจากออกกำลังกาย",
  str_homestory_N24diaoyu_90050206_4_dialog_content = "ฉันจะยกโทษให้คุณสำหรับก่อนหน้านี้แล้ว",
  str_homestory_N24diaoyu_90050206_5_dialog_content = "แต่อย่าคิดว่าฉันทำดีที่สุดแล้ว ฉันปล่อยคุณไปง่ายๆ",
  str_homestory_N24diaoyu_90050206_6_dialog_content = "คุณปล่อยฉันไปง่าย ๆ เหรอ? คุณยอดเยี่ยมมาก Fia!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050206_7_dialog_content = "โอ้ ตอนนี้คุณเป็นแค่นักเลงหัวไม้!",
  str_homestory_N24diaoyu_90050206_8_dialog_content = "คุณควรสละเวลาสักนิดหากต้องการเป็นแชมป์",
  str_homestory_N24diaoyu_90050206_9_dialog_content = "ตอนนี้ออกไปตีสาม <color=#FFB400>นักตกปลาระดับปรมาจารย์</color>!",
  str_homestory_N24diaoyu_90050206_10_dialog_content = "ประตูสู่แชมป์จะเปิดได้ก็ต่อเมื่อคุณเอาชนะนักตกปลาระดับปรมาจารย์สามคนได้เท่านั้น",
  str_homestory_N24diaoyu_90050206_11_dialog_content = "ฉันจะรอผลลัพธ์ของคุณ",
  str_homestory_N24diaoyu_90050206_12_dialog_content = "ค่ะ!",
  str_homestory_N24diaoyu_90050301_1_dialog_content = "นี่ PlayerName!",
  str_homestory_N24diaoyu_90050301_2_dialog_content = "อ้าว บร็อค? มาทำอะไรที่นี่น่ะ?",
  str_homestory_N24diaoyu_90050301_3_dialog_content = "เหมือนเดิม เหมือนเดิม การฝึกอบรมทุกวันแน่นอน<sprite=emo_yaling size=60 />",
  str_homestory_N24diaoyu_90050301_4_dialog_content = "ฉันฝึกฝนอย่างไม่รู้จักเหน็ดเหนื่อยทุกวันเพื่อเตรียมพร้อมสำหรับการครองบัลลังก์ของ Rediesel Wrench",
  str_homestory_N24diaoyu_90050301_5_dialog_content = "ครับ... ผมจะลาคุณแล้ว...",
  str_homestory_N24diaoyu_90050301_6_dialog_content = "เดี๋ยวนะ",
  str_homestory_N24diaoyu_90050301_7_dialog_content = "เฮ้, PlayerName, ถือไว้. คุณไม่รู้สึกว่ามีอะไรขาดหายไปใน Cloud Gardens เหรอ?",
  str_homestory_N24diaoyu_90050301_8_dialog_content = "อืม? สิ่งที่ขาดหายไป?",
  str_homestory_N24diaoyu_90050301_9_dialog_content = "หากคุณกำลังเสนอบางสิ่ง ฉันแน่ใจว่ามันไม่มีประโยชน์<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050301_10_dialog_content = "<sprite=emo_shengqi size=60 />เฮ้! PlayerName! คุณพูดอย่างนั้นได้อย่างไร? ฉันไม่ใช่เพื่อนที่ดีที่สุดของคุณเหรอ?",
  str_homestory_N24diaoyu_90050301_11_dialog_content = "ฉันจริงจังมาก! อย่างน้อยที่สุดที่คุณทำได้คือฟัง!",
  str_homestory_N24diaoyu_90050301_12_dialog_content = "สบายดี ไปข้างหน้า",
  str_homestory_N24diaoyu_90050301_13_dialog_content = "อะแฮ่ม! คุณไม่คิดว่าเราต้องการโรงฝึกร่างกายขนาดใหญ่ที่นี่หรือ",
  str_homestory_N24diaoyu_90050301_14_dialog_content = "สำหรับนักกีฬาเช่นฉัน มันเหงาและน่าเบื่อใน Cloud Gardens",
  str_homestory_N24diaoyu_90050301_15_dialog_content = "ทำไมคุณไม่เพียงแค่หาอาคารและวิ่งไปรอบ ๆ",
  str_homestory_N24diaoyu_90050301_16_dialog_content = "นั่นคือแอโรบิก สิ่งที่ฉันต้องการคือการฝึกความต้านทานที่มีความเข้มสูง!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050301_17_dialog_content = "<sprite=emo_yihuo size=60 />ความเข้มสูง... ฝึกอะไรอีก?",
  str_homestory_N24diaoyu_90050301_18_dialog_content = "แค่หาแร่มาให้ฉัน แล้วฉันจะสร้างเครื่องฝึกฝนให้นาย!",
  str_homestory_N24diaoyu_90050301_19_dialog_content = "ฮะ? ไม่มีทาง. ตอนนี้ฉันไม่ว่าง!",
  str_homestory_N24diaoyu_90050301_20_dialog_content = "มัวทำอะไรอยู่? คุณยุ่งอยู่กับการตามหานักตกปลาระดับปรมาจารย์ใช่ไหม?",
  str_homestory_N24diaoyu_90050301_21_dialog_content = "รู้ได้ไง",
  str_homestory_N24diaoyu_90050301_22_dialog_content = "สิ่งที่คุณต้องรู้คือ: คุณช่วยฉัน และฉันก็ช่วยคุณ",
  str_homestory_N24diaoyu_90050301_23_dialog_content = "ก็ได้... ฉันจะเชื่อใจคุณ",
  str_homestory_N24diaoyu_90050302_1_dialog_content = "คุณพอ? ฉันรอไม่ไหวแล้ว!",
  str_homestory_N24diaoyu_90050302_2_dialog_content = "ดี! พวกเขาทั้งหมดอยู่ที่นี่ ({1}/{2})",
  str_homestory_N24diaoyu_90050302_3_dialog_content = "อีกเพียงเล็กน้อย รออีกสักหน่อย",
  str_homestory_N24diaoyu_90050302_4_dialog_content = "มาเร็ว! เลือดของฉันกำลังเดือดพล่าน!",
  str_homestory_N24diaoyu_90050302_5_dialog_content = "ฉันต้องบอกว่าคุณมีรูปร่างที่ดีทีเดียว PlayerName.",
  str_homestory_N24diaoyu_90050302_6_dialog_content = "หยุดยุ่งกับฉัน แค่บอกสิ่งที่ฉันต้องรู้เกี่ยวกับการแข่งขัน!",
  str_homestory_N24diaoyu_90050302_7_dialog_content = "ไม่ต้องกังวลฉันจะบอกคุณ เฟลอร์เป็นนักตกปลาระดับปรมาจารย์",
  str_homestory_N24diaoyu_90050302_8_dialog_content = "อะไร เฟลอร์เป็นนักตกปลาระดับปรมาจารย์? ฉันคิดว่า Rediesel Wrench ตั้งอยู่ในทะเลทราย...",
  str_homestory_N24diaoyu_90050302_9_dialog_content = "แล้วไง พวกเขาตกปลาหนอนทรายไม่เก่งหรืออะไรทำนองนั้น",
  str_homestory_N24diaoyu_90050302_10_dialog_content = "คุณไม่ควรประมาทเขาเพียงเพราะเขาเป็นสมาชิกของ Rediesel Wrench",
  str_homestory_N24diaoyu_90050302_11_dialog_content = "ฉันเรียนรู้จากประสบการณ์",
  str_homestory_N24diaoyu_90050302_12_dialog_content = "ตกลง. ฉันจะไปหาเฟลอร์",
  str_homestory_N24diaoyu_90050302_13_dialog_content = "ภายหลัง!",
  str_homestory_N24diaoyu_90050303_1_dialog_content = "เฟลอร์!",
  str_homestory_N24diaoyu_90050303_2_dialog_content = "โอ้เฮ้ PlayerName.",
  str_homestory_N24diaoyu_90050303_3_dialog_content = "คุณมาที่นี่เพื่อชิมหรือไม่?",
  str_homestory_N24diaoyu_90050303_4_dialog_content = "<sprite=emo_yihuo size=60 />งานชิมอะไร?",
  str_homestory_N24diaoyu_90050303_5_dialog_content = "ฉันได้ยินมาจาก Brock ว่าคุณเป็นนักตกปลาระดับปรมาจารย์ ฉันมาที่นี่เพื่อท้าทายคุณ!",
  str_homestory_N24diaoyu_90050303_6_dialog_content = "ถูกต้อง. ฉันสมัครเข้าร่วมกิจกรรมนั้นซึ่งแจกคันเบ็ดฟรีเพื่อรวบรวมวัตถุดิบทำอาหารและฉันได้ปลามาสองสามตัว...",
  str_homestory_N24diaoyu_90050303_7_dialog_content = "เดาว่านั่นเป็นวิธีที่ฉันกลายเป็นนักตกปลาระดับปรมาจารย์",
  str_homestory_N24diaoyu_90050303_8_dialog_content = "พูดเหมือนไม่มีอะไร ฉันคิดว่าคุณเป็นนักตกปลาที่ดีจริงๆ เฟลอร์",
  str_homestory_N24diaoyu_90050303_9_dialog_content = "อย่ารอช้า! PlayerName Dragonwave Angler ท้าทายคุณ!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050303_10_dialog_content = "ตอนนี้ยังไม่ใช่เวลา เสียใจ.",
  str_homestory_N24diaoyu_90050303_11_dialog_content = "แต่ ทำไมล่ะ",
  str_homestory_N24diaoyu_90050303_12_dialog_content = "อย่างที่บอกว่ากำลังเตรียมวัตถุดิบสำหรับชิมอยู่<sprite=emo_rou size=60 />",
  str_homestory_N24diaoyu_90050303_13_dialog_content = "นี่เป็นวิธีการทำอาหารใหม่ที่ฉันเพิ่งเรียนรู้",
  str_homestory_N24diaoyu_90050303_14_dialog_content = "ให้บริการอาหารทะเลสดโดยปรุงรสให้น้อยที่สุดเพื่อรักษารสชาติดั้งเดิมของวัตถุดิบ",
  str_homestory_N24diaoyu_90050303_15_dialog_content = "อย่างไรก็ตาม ฉันแค่มีวัตถุดิบทำอาหารไม่เพียงพอ ช่างเป็นอะไรที่ปวดหัว",
  str_homestory_N24diaoyu_90050303_16_dialog_content = "ฉันจะช่วยคุณค่ะ!",
  str_homestory_N24diaoyu_90050303_17_dialog_content = "จริงหรือ คุณจะทำเพื่อฉัน?",
  str_homestory_N24diaoyu_90050303_18_dialog_content = "ถ้าคุณเต็มใจช่วย ฉันจะเตรียมให้พร้อม เพื่อที่เราจะได้เริ่มการแข่งขันเล็กๆ ของเรา วิธีที่ว่า, PlayerName?",
  str_homestory_N24diaoyu_90050303_19_dialog_content = "หาปลาโลมาให้ฉันหน่อย คุณสามารถคิดว่ามันเป็นการอุ่นเครื่อง PlayerName.",
  str_homestory_N24diaoyu_90050303_20_dialog_content = "เชื่อมือฉันได้เลย",
  str_homestory_N24diaoyu_90050304_1_dialog_content = "คุณได้รับปลาโลกเพียงพอหรือไม่?",
  str_homestory_N24diaoyu_90050304_2_dialog_content = "ใช่! ({1}/{2})",
  str_homestory_N24diaoyu_90050304_3_dialog_content = "อีกเพียงไม่กี่ คุณจะได้รับเร็ว ๆ นี้!",
  str_homestory_N24diaoyu_90050304_4_dialog_content = "ตกลง. ขอบคุณมาก.",
  str_homestory_N24diaoyu_90050304_5_dialog_content = "ขอบคุณนะ PlayerName",
  str_homestory_N24diaoyu_90050304_6_dialog_content = "ปลาเหล่านี้แน่ใจว่าสดและมีชีวิตอยู่",
  str_homestory_N24diaoyu_90050304_7_dialog_content = "คุณจะเตรียมปลาอย่างไร",
  str_homestory_N24diaoyu_90050304_8_dialog_content = "ก็... ปลาต่างชนิดกันต้องการวิธีการที่แตกต่างกัน",
  str_homestory_N24diaoyu_90050304_9_dialog_content = "บางส่วนต้องถูกเลาะออก และส่วนหัวและอวัยวะภายในที่ไม่เหมาะสำหรับการรับประทานก็ต้องถูกเอาออกก่อนเช่นกัน",
  str_homestory_N24diaoyu_90050304_10_dialog_content = "จากนั้นฉันสามารถแล่เนื้อที่สวยงามและผสมกับ Lumina เพื่อฆ่าปรสิตในนั้น",
  str_homestory_N24diaoyu_90050304_11_dialog_content = "คุณสามารถใช้ Lumina เพื่อสิ่งนั้น!?<sprite=emo_cangshu size=60 />",
  str_homestory_N24diaoyu_90050304_12_dialog_content = "ได้. เป็นสิ่งที่ฉันเพิ่งเรียนรู้เหมือนกัน",
  str_homestory_N24diaoyu_90050304_13_dialog_content = "สำหรับปลาโกเบที่คุณเพิ่งนำเข้ามา ฉันต้องเอาอวัยวะภายใน ดวงตา หรือแม้แต่เลือดออกอย่างระมัดระวัง",
  str_homestory_N24diaoyu_90050304_14_dialog_content = "เอาจริงๆพอมาคิดๆดูแล้วต้องมีคนไม่พอใจปลาดิบแน่ๆ",
  str_homestory_N24diaoyu_90050304_15_dialog_content = "การรับประทานมันดิบอาจทำให้อาหารไม่ย่อยในบางคน",
  str_homestory_N24diaoyu_90050304_16_dialog_content = "ฉันสงสัยว่าคุณจะหาน้ำจืดให้ฉันได้ไหม PlayerName?",
  str_homestory_N24diaoyu_90050304_17_dialog_content = "มันคงจะสมบูรณ์แบบถ้าฉันสามารถเตรียมซุปปลาให้ทุกคนได้<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050304_18_dialog_content = "เข้าใจแล้วครับ",
  str_homestory_N24diaoyu_90050305_1_dialog_content = "คุณมีน้ำ?",
  str_homestory_N24diaoyu_90050305_2_dialog_content = "ใช่ เสร็จแล้ว! ({1}/{2})",
  str_homestory_N24diaoyu_90050305_3_dialog_content = "ยัง. ให้เวลาฉันหน่อย.",
  str_homestory_N24diaoyu_90050305_4_dialog_content = "แน่นอน. ขอขอบคุณ.",
  str_homestory_N24diaoyu_90050305_5_dialog_content = "ขอบคุณล้าน คุณต้องรอฉันสักหน่อย หลังจากเตรียมอาหารแล้ว อยากลองชิมก่อนไหม?",
  str_homestory_N24diaoyu_90050305_6_dialog_content = "จริงหรือ ฉันไม่มีของฉัน—เดี๋ยวก่อน ฉันมาที่นี่เพื่อท้าทายคุณ!",
  str_homestory_N24diaoyu_90050305_7_dialog_content = "นั่นอาจเป็นความจริง PlayerName. โปรดเลือกอย่างใดอย่างหนึ่งก่อน กินหรือแข่งขัน?",
  str_homestory_N24diaoyu_90050305_8_option_content = "กิน",
  str_homestory_N24diaoyu_90050305_9_dialog_content = "ยอดเยี่ยม. กรุณารอที่นี่ อาหารควรพร้อมภายในสองชั่วโมง",
  str_homestory_N24diaoyu_90050305_10_dialog_content = "มานานแล้วว่า? มาทำการแข่งขันกันก่อน!",
