  str_homestory_N24diaoyu_90050501_12_dialog_content = "ฉันอิจฉา.",
  str_homestory_N24diaoyu_90050501_13_dialog_content = "อิจฉาที่คุณมีสุขภาพดีและสามารถเข้าร่วมการแข่งขันตกปลาได้ PlayerName.",
  str_homestory_N24diaoyu_90050501_14_dialog_content = "ฉันอิจฉามาก",
  str_homestory_N24diaoyu_90050501_15_dialog_content = "อืม... ทำไมคุณไม่ลองสมัครดูล่ะ ถ้าคุณต้องการเข้าร่วมด้วย",
  str_homestory_N24diaoyu_90050501_16_dialog_content = "ฉันเป็นนักตกปลาอยู่แล้ว",
  str_homestory_N24diaoyu_90050501_17_dialog_content = "แต่ฉันต้องการเข้าร่วมทีมนักตกปลา",
  str_homestory_N24diaoyu_90050501_18_dialog_content = "น่าเศร้าที่หัวหน้าทีมปฏิเสธฉันโดยบอกว่าฉันซึมเศร้าเกินไป",
