  str_homestory_N24diaoyu_90050501_20_dialog_content = "อะไร!? ข้ออ้างแบบนั้นคืออะไร?",
  str_homestory_N24diaoyu_90050501_21_dialog_content = "ไม่มีโอกาสที่ฉันจะทิ้งคุณไว้แบบนี้ตอนนี้ฉันรู้เรื่องนี้แล้ว! มา. ฉันจะพูดกับหัวหน้าหน่วยนั้น!",
  str_homestory_N24diaoyu_90050502_1_dialog_content = "ถึงแล้วล่ะ",
  str_homestory_N24diaoyu_90050502_2_dialog_content = "ทีนี้มาดูกันว่าใครกันที่กล้ารังแก Axelia!",
