  str_homestory_N24diaoyu_90050502_6_dialog_content = "โอ้, PlayerName.",
  str_homestory_N24diaoyu_90050502_7_dialog_content = "การประกวดเป็นอย่างไร? อย่าร้องไห้เพียงเพราะคุณแพ้ผู้เข้าแข่งขันคนอื่น",
  str_homestory_N24diaoyu_90050502_8_dialog_content = "ไม่มีทาง! ฉันได้เอาชนะนักตกปลาระดับปรมาจารย์สองคนแล้ว!",
