  str_homestory_N24diaoyu_90050502_10_dialog_content = "และฉันเคยเอาชนะบาร์ตันด้วย!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050502_11_dialog_content = "(แม้ว่า Barton ทำให้ฉันอับอายก่อนก็ตาม)",
  str_homestory_N24diaoyu_90050502_12_dialog_content = "ว้าว ฉันประทับใจจริงๆ ฉันไม่คิดว่าคุณมีมันอยู่ในตัวคุณ PlayerName.",
  str_homestory_N24diaoyu_90050502_13_dialog_content = "ฉันจะบอกคุณเพิ่มเติมเกี่ยวกับปลาที่นี่เพื่อช่วยคุณ",
  str_homestory_N24diaoyu_90050502_14_dialog_content = "ฉันเป็นนักตกปลาที่ดีจริงๆ ฉันไม่ต้องการสิ่งนั้นเพื่อชนะ... เดี๋ยวก่อน นั่นไม่ใช่สิ่งที่ฉันมาที่นี่",
  str_homestory_N24diaoyu_90050502_15_dialog_content = "แล้วทำไมคุณถึงมาอยู่ที่นี่?",
