  str_homestory_N24diaoyu_90050502_17_dialog_content = "ฉันแน่ใจว่าได้! ทีมฟูลเฮาส์!",
  str_homestory_N24diaoyu_90050502_18_dialog_content = "ทำไมคุณไม่ให้ Axelia เข้าร่วม",
