  str_homestory_N24diaoyu_90050502_20_dialog_content = "ก็... ท- นั่นเพราะว่า...",
  str_homestory_N24diaoyu_90050502_21_dialog_content = "บุคลิกของเธอไม่เข้ากับทีมของเราเลย",
