  str_homestory_N24diaoyu_90050502_23_dialog_content = "สีสันเฉพาะตัวเป็นสิ่งสำคัญมากสำหรับสมาชิกในทีมนี้!",
  str_homestory_N24diaoyu_90050502_24_dialog_content = "แต่คุณยังไม่เปิดโอกาสให้เธอแสดงความสามารถเลยใช่ไหม?",
  str_homestory_N24diaoyu_90050502_25_dialog_content = "คุณคิดว่ามันถูกต้องหรือไม่ที่จะตัดสินหนังสือจากปก<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050502_26_dialog_content = "ทำไมจู่ ๆ คุณถึงทำงานหนักขึ้นแบบนั้น!?",
  str_homestory_N24diaoyu_90050502_27_dialog_content = "ฉันหมายความว่ามีข้อกำหนดในการเข้าร่วมทีม ถ้าเธอมีจริงก็พิสูจน์สิ!",
  str_homestory_N24diaoyu_90050502_28_dialog_content = "ไปเก็บแร่ ไม้ หรือปลา! เพียงแสดงหลักฐานให้ฉันเห็นก่อน!",
  str_homestory_N24diaoyu_90050502_29_dialog_content = "ไม่ต้องกังวล Axelia คุณไปรวบรวมแร่และไม้ ฉันจะช่วยคุณหาปลา",
