  str_homestory_N24diaoyu_90050503_1_dialog_content = "คุณมีทุกสิ่งทุกอย่าง?",
  str_homestory_N24diaoyu_90050503_2_dialog_content = "พาพวกเขามาที่นี่! ({1}/{2})",
