  str_homestory_N24diaoyu_90050503_5_dialog_content = "คุณสามารถยอมแพ้ได้ตลอดเวลา",
  str_homestory_N24diaoyu_90050503_6_dialog_content = "ดี. ฉันยอมรับว่าฉันตัดสินคุณเร็วเกินไป คุณอาจมีสิ่งที่จะอยู่ในทีม",
  str_homestory_N24diaoyu_90050503_7_dialog_content = "นั่นเป็นข่าวดี Axelia",
  str_homestory_N24diaoyu_90050503_8_dialog_content = "ขอบคุณทีช่วยฉัน, PlayerName.",
  str_homestory_N24diaoyu_90050503_9_dialog_content = "<sprite=emo_wuzui size=60 />รอ. เคยทำ PlayerName คุณช่วยรวบรวมพวกเขา?",
  str_homestory_N24diaoyu_90050503_10_dialog_content = "ใช่. แล้วไง",
