  str_homestory_N24diaoyu_90050503_15_dialog_content = "ดะ-เดี๋ยวก่อน เฟีย! ฉันคิดว่าคุณบอกว่าจะยกโทษให้ฉันก่อนหน้านี้!",
  str_homestory_N24diaoyu_90050503_16_dialog_content = "ฉันยกโทษให้คุณชั่วคราว! ไม่เอาไว้ข้างหลังฉัน!",
  str_homestory_N24diaoyu_90050503_17_dialog_content = "ฮึ ดูเหมือนว่าฉันต้องการให้คุณเข้ามาแทนที่ PlayerName!",
  str_homestory_N24diaoyu_90050503_18_dialog_content = "มาทำในแบบที่เราทำระหว่างนักตกปลาสองคนกันเถอะ!",
  str_homestory_N24diaoyu_90050503_19_dialog_content = "หยิบเบ็ดตกปลาของคุณออกมา และอย่าคิดว่าฉันจะยอมง่ายๆ กับคุณในครั้งนี้!",
  str_homestory_N24diaoyu_90050503_20_dialog_content = "ฉันจะทำให้คุณร้องขอและร้องไห้!",
  str_homestory_N24diaoyu_90050503X1_1_dialog_content = "คุณโง่ PlayerName! มาที่นี่เพื่อที่ฉันจะได้เอาชนะคุณ!",
  str_homestory_N24diaoyu_90050503X1_2_option_content = "ฉันจะไม่มีวันยอมรับความพ่ายแพ้!",
