  str_homestory_N24diaoyu_90050504_1_dialog_content = "<sprite=emo_hanshui size=60 />ฮึ่ม... ฮึ่ม... เฟียเก่งจริงๆ",
  str_homestory_N24diaoyu_90050504_2_dialog_content = "นี่คือสิ่งที่คุณได้รับจริงหรือ?",
  str_homestory_N24diaoyu_90050504_3_dialog_content = "โชคดีที่ฉันสามารถคว้าชัยชนะมาได้ คุณสามารถสงบสติอารมณ์ตอนนี้?",
  str_homestory_N24diaoyu_90050504_4_dialog_content = "<sprite=emo_xinsui size=60 />ฉัน... ฉันไม่อยากจะเชื่อเลย",
  str_homestory_N24diaoyu_90050504_5_dialog_content = "แต่เกียรติยศคือทุกสิ่งสำหรับนักตกปลา ฉันจะถือว่าสิ่งที่เกิดขึ้นก่อนหน้านี้เป็นคำขอโทษ",
  str_homestory_N24diaoyu_90050504_6_dialog_content = "Axelia ฉันขอต้อนรับคุณอย่างเป็นทางการในฐานะสมาชิกคนที่สองของทีม",
  str_homestory_N24diaoyu_90050504_7_dialog_content = "ขอบคุณ. ฉันจะทำให้ดีที่สุด.",
  str_homestory_N24diaoyu_90050504_8_dialog_content = "(อะไรนะ มีแค่สองคนในทีมเหรอ ทำไมเธอถึงอยากเข้าร่วมทีมแบบนี้ตั้งแต่แรก?)",
  str_homestory_N24diaoyu_90050504_9_dialog_content = "นั่นคือสิ่งที่ฉันเรียกว่าตอนจบที่ดี ฉันควรจะไปหา Master Angler คนต่อไป",
