  str_homestory_N24diaoyu_90050504_11_dialog_content = "คุณเอาชนะเฟลอร์และอาซัวร์ได้แล้ว ฉันเป็นคนเดียวที่เหลืออยู่",
  str_homestory_N24diaoyu_90050504_12_dialog_content = "อะไร คุณเป็นนักตกปลาระดับปรมาจารย์? ฉันคิดว่าคุณเป็นผู้สอน",
  str_homestory_N24diaoyu_90050504_13_dialog_content = "ใครว่าผู้สอนจะเป็นนักตกปลาระดับปรมาจารย์ไม่ได้?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050504_14_dialog_content = "ทุบตีฉันโดยไม่รู้ตัวงั้นเหรอ? คุณกำลังโกรธจริงๆ คุณรู้ไหม",
  str_homestory_N24diaoyu_90050504_15_dialog_content = "มา! ลุ้นกันอีกสักรอบ!",
  str_homestory_N24diaoyu_90050601_1_dialog_content = "มือของฉันเจ็บมาก <sprite=emo_xuanyun size=60 />เฟียลากไปตกปลาสิบกว่าชั่วโมงรวด...",
  str_homestory_N24diaoyu_90050601_2_dialog_content = "แต่ฉันเอาชนะนักตกปลาระดับปรมาจารย์สามคนได้แล้ว! PlayerName Dragonwave Angler คว้าชัยชนะอีกครั้ง!",
  str_homestory_N24diaoyu_90050601_3_dialog_content = "ฮ่าฮ่าฮ่า! ตอนนี้ฉันควรจะได้คันเบ็ดที่เป็นรางวัล ขายมัน และเอาเงินไปสร้างพิพิธภัณฑ์ได้แล้ว!",
  str_homestory_N24diaoyu_90050601_4_dialog_content = "ฉันแข่งขันกับคนอื่นมานานแล้ว ฉันแทบจะลืมความสุขในการตกปลาแบบสบายๆ คนเดียวไปเลย",
  str_homestory_N24diaoyu_90050601_5_dialog_content = "ขอผมทำอย่างนั้นเพื่อผ่อนคลาย",
  str_homestory_N24diaoyu_90050601_6_dialog_content = "<sprite=emo_wuzui size=60 />อืม!? แรงขนาดนี้!",
  str_homestory_N24diaoyu_90050601_7_dialog_content = "ปลาเหลือเชื่อแค่กัดเหยื่อ!",
  str_homestory_N24diaoyu_90050601_8_dialog_content = "ห๊ะ!!",
  str_homestory_N24diaoyu_90050601_9_dialog_content = "<sprite=emo_baimao size=60 />อืม...เหมียว",
  str_homestory_N24diaoyu_90050601_10_dialog_content = "อะ-อะไร...",
  str_homestory_N24diaoyu_90050601_11_dialog_content = "ฟิลลี่อาย!? ยังไง!?",
  str_homestory_N24diaoyu_90050601_12_dialog_content = "หรือนี่คือปลาชนิดหนึ่งที่มีลักษณะคล้ายฟิลิชี่?",
  str_homestory_N24diaoyu_90050601_13_dialog_content = "อุ๊ย! มันเจ็บ, PlayerName! ฉันเอง Philyshy! เหมียว!<sprite=emo_baimao size=60 />",
  str_homestory_N24diaoyu_90050601_14_dialog_content = "แต่... ทำไมเธอถึงโดนฉันจับเหมือนปลาล่ะ?",
  str_homestory_N24diaoyu_90050601_15_dialog_content = "มันสำคัญไหมตอนนี้? เร็วเข้า เหมียว! ส่งเอกสารนี้ให้เจ้าหน้าที่วิเวียนเพื่อฉัน!",
  str_homestory_N24diaoyu_90050602_1_dialog_content = "คุณวิเวียน!",
  str_homestory_N24diaoyu_90050602_2_dialog_content = "PlayerName? ทำไมคุณถึงรีบร้อน?",
