  str_homestory_N24diaoyu_90050602_5_dialog_content = "ขอฉันดูหน่อย... อืม นี่น่าจะอยู่บนโต๊ะฉันตั้งแต่เมื่อวานแล้ว",
  str_homestory_N24diaoyu_90050602_6_dialog_content = "<sprite=emo_shengqi size=60 />Philyshy... บางครั้งฉันก็สงสัยว่าเธอทำอะไรอยู่",
